<?php
namespace App\Domain\Network\Commerce;
use App\Domain\Network\Commerce\Contracts\PlatformPaymentProvider;use App\Domain\Network\Commerce\Models\{PlatformPaymentAttempt,TenantSaasOrder};use Illuminate\Http\Request;use Illuminate\Support\Facades\Http;use RuntimeException;
final class MercadoPagoPlatformPaymentProvider implements PlatformPaymentProvider{private function cfg(string$k,mixed$d=null):mixed{return config('zigo_payments.'.$k,$d);}public function accountId():string{return(string)$this->cfg('platform.account_id');}public function createCheckout(PlatformPaymentAttempt$a,TenantSaasOrder$o):array{$token=(string)$this->cfg('platform.access_token');$webhook=(string)$this->cfg('platform.webhook_url');if(!$token||!$webhook)throw new RuntimeException('ZIGO platform payments no está configurado.');$return=url('/admin/compras/'.$o->uuid.'/retorno');$body=['items'=>[['id'=>$o->purchase_snapshot['code'],'title'=>$o->purchase_snapshot['name'],'quantity'=>1,'currency_id'=>$o->currency,'unit_price'=>(float)$o->total_amount]],'external_reference'=>$a->external_reference,'back_urls'=>['success'=>$return.'/success','pending'=>$return.'/pending','failure'=>$return.'/failure'],'auto_return'=>'approved','notification_url'=>$webhook.'?saas_attempt='.$a->uuid,'expires'=>true,'expiration_date_to'=>$o->expires_at?->toIso8601String()];$r=Http::acceptJson()->asJson()->withToken($token)->withHeaders(['X-Idempotency-Key'=>$a->uuid])->post(rtrim((string)$this->cfg('providers.mercado_pago.api_url'),'/').'/checkout/preferences',$body);if(!$r->successful())throw new RuntimeException('Mercado Pago no pudo crear el checkout SaaS.');return$r->json();}public function retrievePayment(string$id):array{$r=Http::acceptJson()->withToken((string)$this->cfg('platform.access_token'))->get(rtrim((string)$this->cfg('providers.mercado_pago.api_url'),'/').'/v1/payments/'.rawurlencode($id));if(!$r->successful())throw new RuntimeException('No fue posible verificar el pago SaaS.');return$r->json();}public function validateWebhook(Request$r,string$id):bool{$secret=(string)$this->cfg('platform.webhook_secret');$sig=(string)$r->header('x-signature');$rid=(string)$r->header('x-request-id');preg_match('/(?:^|,)\s*ts=([^,]+)/',$sig,$tm);preg_match('/(?:^|,)\s*v1=([^,]+)/',$sig,$vm);if(!$secret||!$rid||!isset($tm[1],$vm[1])||!ctype_digit($tm[1]))return false;$issued=(int)$tm[1];if($issued>99999999999)$issued=(int)floor($issued/1000);if(abs(time()-$issued)>(int)$this->cfg('providers.mercado_pago.webhook_tolerance_seconds',300))return false;$manifest='id:'.strtolower(trim($id)).';request-id:'.$rid.';ts:'.$tm[1].';';return hash_equals(hash_hmac('sha256',$manifest,$secret),trim($vm[1]));}}
